/// Language Forge Phase 3 — the Naming Convention Builder.
///
/// A convention is how one people builds a person's full name: the shape of
/// a given name, the shape of a family name, whether a child carries a
/// parent's name as a patronymic or matronymic, whether rank adds a particle,
/// and in what order the parts are said. Two conventions over one language —
/// the coast and the capital, commoners and nobility, daughters and sons — are
/// what make characters of one culture sound related without sounding the
/// same.
///
/// Every part is a [WordShape] generated by the same [WordForge], so every
/// generated part obeys the language's sound rules. A patronymic is built from
/// a parent's name the author supplies (or a forged one), and is kept only if
/// the language could say it.
///
/// ## What is not modelled
///
/// A convention generates. It does not assign: a character's name remains the
/// character record's title, set by the author in Character Studio. Clan,
/// regnal, religious, earned and secret names are the author's to record on the
/// character; the brief's list of them is a checklist for the convention's
/// notes, not a set of fields here.
library;

import '../procedural/generation_seed.dart';
import 'phonology.dart';
import 'word_forge.dart';

/// Which part of a full name is said first.
enum NameOrder {
  givenFirst,
  familyFirst;

  String get label => switch (this) {
        NameOrder.givenFirst => 'Given name first',
        NameOrder.familyFirst => 'Family name first',
      };
}

/// A child's name taken from a parent's: *Aranson*, *ben Aran*, *Aranovna*.
class ParentNameRule {
  const ParentNameRule({this.prefix = '', this.suffix = '', this.label = ''});

  /// A separate word before the parent's name — `ben`, `ap`, `mac`.
  final String prefix;

  /// Joined to the end of the parent's name — `son`, `ovna`.
  final String suffix;

  /// `Patronymic`, `Matronymic` — the author's word for it.
  final String label;

  bool get isEmpty => prefix.trim().isEmpty && suffix.trim().isEmpty;

  String apply(String parent) {
    final base = '$parent${suffix.trim()}';
    return prefix.trim().isEmpty ? base : '${prefix.trim()} $base';
  }

  Map<String, Object?> toJson() => {
        if (prefix.isNotEmpty) 'prefix': prefix,
        if (suffix.isNotEmpty) 'suffix': suffix,
        if (label.isNotEmpty) 'label': label,
      };

  factory ParentNameRule.fromJson(Map<String, Object?> json) => ParentNameRule(
        prefix: json['prefix'] as String? ?? '',
        suffix: json['suffix'] as String? ?? '',
        label: json['label'] as String? ?? '',
      );
}

class NamingConvention {
  const NamingConvention({
    required this.id,
    required this.name,
    required this.languageId,
    this.scopeRecordId,
    this.given = WordShape.givenName,
    this.family,
    this.parentName,
    this.particle = '',
    this.order = NameOrder.givenFirst,
    this.notes = '',
  });

  final String id;

  /// `Coastal nobility`, `Daughters of the river`.
  final String name;

  /// The `language` or `dialect` record whose sounds the names use.
  final String languageId;

  /// The culture, faction, House or place the convention belongs to, if the
  /// author has said. A reference to a canonical record, never a copy.
  final String? scopeRecordId;

  final WordShape given;

  /// Null for a people without family names.
  final WordShape? family;

  final ParentNameRule? parentName;

  /// A rank or origin word before the family name — `of`, `von`, `al-`.
  final String particle;

  final NameOrder order;

  /// What the fields cannot say: when the adult name is taken, which names
  /// are secret, how marriage changes things.
  final String notes;

  NamingConvention copyWith({
    String? name,
    String? scopeRecordId,
    WordShape? given,
    WordShape? family,
    bool clearFamily = false,
    ParentNameRule? parentName,
    bool clearParentName = false,
    String? particle,
    NameOrder? order,
    String? notes,
  }) =>
      NamingConvention(
        id: id,
        name: name ?? this.name,
        languageId: languageId,
        scopeRecordId: scopeRecordId ?? this.scopeRecordId,
        given: given ?? this.given,
        family: clearFamily ? null : family ?? this.family,
        parentName: clearParentName ? null : parentName ?? this.parentName,
        particle: particle ?? this.particle,
        order: order ?? this.order,
        notes: notes ?? this.notes,
      );

  Map<String, Object?> toJson() => {
        'id': id,
        'name': name,
        'languageId': languageId,
        if (scopeRecordId != null) 'scopeRecordId': scopeRecordId,
        'given': given.toJson(),
        if (family != null) 'family': family!.toJson(),
        if (parentName != null) 'parentName': parentName!.toJson(),
        if (particle.isNotEmpty) 'particle': particle,
        'order': order.name,
        if (notes.isNotEmpty) 'notes': notes,
      };

  factory NamingConvention.fromJson(Map<String, Object?> json) {
    Map<String, Object?>? map(Object? value) =>
        value is Map ? Map<String, Object?>.from(value) : null;
    final family = map(json['family']);
    final parent = map(json['parentName']);
    return NamingConvention(
      id: json['id'] as String,
      name: json['name'] as String,
      languageId: json['languageId'] as String,
      scopeRecordId: json['scopeRecordId'] as String?,
      given: WordShape.fromJson(map(json['given']) ?? const {}),
      family: family == null ? null : WordShape.fromJson(family),
      parentName: parent == null ? null : ParentNameRule.fromJson(parent),
      particle: json['particle'] as String? ?? '',
      order: NameOrder.values.byName(json['order'] as String? ?? 'givenFirst'),
      notes: json['notes'] as String? ?? '',
    );
  }
}

/// One generated full name, and its parts.
class ForgedName {
  const ForgedName({
    required this.given,
    this.family,
    this.parentName,
    required this.display,
  });

  final String given;
  final String? family;

  /// The patronymic or matronymic, as said.
  final String? parentName;

  /// The whole name, in the convention's order.
  final String display;
}

abstract final class NameForge {
  /// Up to [count] full names under [convention].
  ///
  /// [parents] are parent given names to build patronymics from — the author's
  /// own characters, usually. Without them a parent's name is forged too.
  /// A name whose patronymic the language could not say is dropped, not
  /// repaired: repairing it would be inventing a rule the author did not write.
  static List<ForgedName> generate(
    NamingConvention convention,
    Phonology phonology,
    GenerationSeed seed, {
    int count = 8,
    List<String> parents = const [],
    Iterable<String> exclude = const [],
  }) {
    final root = seed.derive('names:${convention.id}');
    final givens = WordForge.generate(phonology, root.derive('given'),
            count: count,
            shape: _capitalised(convention.given),
            exclude: exclude)
        .words;
    final families = convention.family == null
        ? const <GeneratedWord>[]
        : WordForge.generate(phonology, root.derive('family'),
                count: count,
                shape: _capitalised(convention.family!),
                exclude: [...exclude, for (final word in givens) word.spelling])
            .words;
    final rule = convention.parentName;
    final parentPool = rule == null || rule.isEmpty
        ? const <String>[]
        : parents.isNotEmpty
            ? parents
            : WordForge.generate(phonology, root.derive('parent'),
                    count: count, shape: _capitalised(convention.given))
                .words
                .map((word) => word.spelling)
                .toList();

    final names = <ForgedName>[];
    for (var i = 0; i < givens.length; i++) {
      final given = givens[i].spelling;
      final family = i < families.length ? families[i].spelling : null;
      String? parentName;
      if (parentPool.isNotEmpty) {
        final parent = parentPool[i % parentPool.length];
        parentName = rule!.apply(parent);
        final joined = '$parent${rule.suffix.trim()}';
        if (!phonology.validate(joined).conforms) continue;
      }
      final familyPart = family == null
          ? null
          : convention.particle.trim().isEmpty
              ? family
              : '${convention.particle.trim()} $family';
      final parts = switch (convention.order) {
        NameOrder.givenFirst => [
            given,
            if (parentName != null) parentName,
            if (familyPart != null) familyPart,
          ],
        NameOrder.familyFirst => [
            if (familyPart != null) familyPart,
            given,
            if (parentName != null) parentName,
          ],
      };
      names.add(ForgedName(
        given: given,
        family: family,
        parentName: parentName,
        display: parts.join(' '),
      ));
    }
    return List.unmodifiable(names);
  }

  static WordShape _capitalised(WordShape shape) => WordShape(
        label: shape.label,
        minSyllables: shape.minSyllables,
        maxSyllables: shape.maxSyllables,
        prefixes: shape.prefixes,
        suffixes: shape.suffixes,
        optionalGroupChance: shape.optionalGroupChance,
        capitalise: true,
      );
}
